s = input().strip()
prec = {"+": 1, "-": 1, "*": 2, "/": 2, "^": 3}
out = []
ops = []
for ch in s:
    if ch.isalnum():
        out.append(ch)
    elif ch == "(":
        ops.append(ch)
    elif ch == ")":
        while ops[-1] != "(":
            out.append(ops.pop())
        ops.pop()
    else:
        while ops and ops[-1] != "(" and (prec[ops[-1]] > prec[ch] or (prec[ops[-1]] == prec[ch] and ch != "^")):
            out.append(ops.pop())
        ops.append(ch)
while ops:
    out.append(ops.pop())
print("".join(out))

