q = int(input())
ins = []
outs = []
res = []
def shift():
    if not outs:
        while ins:
            outs.append(ins.pop())
for _ in range(q):
    p = input().split()
    if p[0] == "enqueue":
        ins.append(p[1])
    elif p[0] == "dequeue":
        shift()
        res.append(outs.pop() if outs else "EMPTY")
    elif p[0] == "front":
        shift()
        res.append(outs[-1] if outs else "EMPTY")
    else:
        res.append(str(len(ins) + len(outs)))
print("\n".join(res))

