from collections import OrderedDict
cap, q = map(int, input().split())
cache = OrderedDict()
out = []
for _ in range(q):
    p = input().split()
    key = int(p[1])
    if p[0] == "get":
        if key in cache:
            cache.move_to_end(key)
            out.append(str(cache[key]))
        else:
            out.append("-1")
    else:
        if key in cache:
            cache.move_to_end(key)
        elif len(cache) >= cap:
            cache.popitem(last=False)
        cache[key] = int(p[2])
print("\n".join(out))

